const body = $input.item.json.body || {};
const handle = (body.instagram_handle || '').trim().toLowerCase().replace(/^@/, '');
if (!handle) throw new Error('Missing instagram_handle');
return { json: { instagram_handle: handle } };

const wrapper = $input.item.json.data || $input.item.json;
const b = wrapper.profile || {};
if (!b.id) throw new Error('Brand profile not found');

const lean = {
  instagram_handle: b.instagram_handle,
  business_name: b.business_name,
  followers_count: b.followers_count,
  bio: (b.bio || '').slice(0, 500),
  city: b.city || b.inferred_city,
  industry: b.industry || b.inferred_industry,
  sub_industry: b.sub_industry || b.inferred_sub_industry,
  has_email: !!(b.manual_email || b.bio_email),
  has_phone: !!(b.manual_phone || b.bio_phone),
  has_whatsapp: !!(b.manual_whatsapp || b.bio_whatsapp),
  website: b.website || b.external_url,
  is_verified: b.is_verified,
  influencer_collab_count: b.influencer_collab_count || 0,
  unique_influencer_partners: b.unique_influencer_partners || 0,
  marketing_intensity: b.marketing_intensity,
  reachability_score: b.reachability_score
};

const prompt = 'Score this brand for outreach suitability.\n\nBrand: ' + JSON.stringify(lean) + '\n\nScoring criteria (each 0-100, weighted):\n1. Instagram Activity (30%): follower count, verification, engagement signals.\n2. Collab History (25%): number of detected influencer collabs, variety of partners, marketing intensity.\n3. Reachability (20%): has bio email, website, phone, WhatsApp.\n4. Market Fit (25%): sub-industry, city presence, realistic outreach.\n\nTier: small (<5K), mid (5K-50K), large (50K-200K), enterprise (>200K).\n\nReturn ONLY valid JSON:\n{"priority_score": 0-100 number, "tier": "small|mid|large|enterprise", "scores": {"instagram_activity": 0, "collab_history": 0, "reachability": 0, "market_fit": 0}, "strengths": [], "concerns": [], "summary": "one paragraph"}';

return { json: {
  instagram_handle: b.instagram_handle,
  claude_body: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: 2048,
    messages: [{ role: 'user', content: prompt }]
  }
} };

let data = {};
try {
  const txt = $input.item.json.content[0].text;
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) data = JSON.parse(m[0]);
} catch (e) { data = { priority_score: 0, tier: 'small', summary: 'Scoring failed' }; }
const instagram_handle = $('Build Claude Prompt').item.json.instagram_handle;
const priority_score = Math.max(0, Math.min(100, Number(data.priority_score) || 0));
const tier_raw = String(data.tier || '').toLowerCase();
const tier = ['small','mid','large','enterprise'].includes(tier_raw) ? tier_raw : 'small';

return { json: {
  instagram_handle, priority_score, tier,
  scoring_summary: String(data.summary || '').slice(0, 2000),
  scoring_strengths: Array.isArray(data.strengths) ? data.strengths : [],
  scoring_concerns: Array.isArray(data.concerns) ? data.concerns : [],
  insight_body: {
    insight_type: 'brand_fit',
    instagram_handle,
    title: 'Brand Score: ' + priority_score + '/100',
    body: String(data.summary || ''),
    score: priority_score,
    model_used: 'claude-sonnet-4',
    metadata: { tier, scores: data.scores || {}, strengths: data.strengths || [], concerns: data.concerns || [] }
  }
} };
